-- =============================================================================
-- Bibliothèque d'exercices de référence (68 exercices).
-- Fichier GÉNÉRÉ par scripts/build-exercise-migration.ts depuis
-- src/domain/exercise-catalog.ts — ne pas modifier à la main.
-- =============================================================================

insert into public.exercise_library (
  slug, name, primary_muscle, secondary_muscles, movement_pattern, equipment, difficulty,
  is_compound, is_timed, caution_areas, instructions
)
values
  ('developpe-couche-barre', 'Développé couché à la barre', 'chest', array['triceps', 'shoulders']::text[], 'push_horizontal', array['barbell', 'bench']::text[], 'intermediate', true, false, array['shoulder']::text[], 'Allongé, pieds au sol, omoplates serrées. Descends la barre jusqu''au bas des pectoraux en gardant les coudes à environ 45° du buste, puis pousse sans décoller les fesses du banc. Avec des charges lourdes, utilise des sécurités ou un partenaire.'),
  ('developpe-couche-halteres', 'Développé couché aux haltères', 'chest', array['triceps', 'shoulders']::text[], 'push_horizontal', array['dumbbells', 'bench']::text[], 'beginner', true, false, array['shoulder']::text[], 'Allongé sur le banc, haltères au-dessus de la poitrine. Descends en contrôlant jusqu''à sentir l''étirement des pectoraux, coudes légèrement rentrés, puis remonte en rapprochant les haltères.'),
  ('developpe-incline-halteres', 'Développé incliné aux haltères', 'chest', array['shoulders', 'triceps']::text[], 'push_horizontal', array['dumbbells', 'bench']::text[], 'intermediate', true, false, array['shoulder']::text[], 'Banc incliné à 30°. Descends les haltères vers le haut de la poitrine, puis pousse vers le haut. Garde les omoplates serrées et le bas du dos en contact avec le banc.'),
  ('pompes', 'Pompes', 'chest', array['triceps', 'shoulders', 'core']::text[], 'push_horizontal', array[]::text[], 'beginner', true, false, array['wrist']::text[], 'Mains un peu plus larges que les épaules, corps gainé de la tête aux talons. Descends la poitrine près du sol, coudes vers l''arrière en diagonale, puis pousse. Trop difficile : fais-les sur les genoux ou mains surélevées.'),
  ('pompes-genoux', 'Pompes sur les genoux', 'chest', array['triceps', 'shoulders']::text[], 'push_horizontal', array[]::text[], 'beginner', true, false, array['wrist']::text[], 'Comme une pompe, mais en appui sur les genoux. Garde une ligne droite des genoux à la tête et descends la poitrine entre les mains.'),
  ('presse-pectoraux-machine', 'Presse pectoraux à la machine', 'chest', array['triceps', 'shoulders']::text[], 'push_horizontal', array['machines']::text[], 'beginner', true, false, array[]::text[], 'Règle le siège pour que les poignées soient à hauteur du milieu de la poitrine. Pousse sans verrouiller brutalement les coudes et reviens lentement.'),
  ('ecarte-halteres', 'Écarté aux haltères', 'chest', array['shoulders']::text[], 'isolation', array['dumbbells', 'bench']::text[], 'intermediate', false, false, array['shoulder']::text[], 'Allongé, bras au-dessus de la poitrine, coudes légèrement fléchis. Ouvre les bras en arc de cercle jusqu''à un étirement confortable, puis referme comme pour enlacer un arbre.'),
  ('ecarte-poulie', 'Écarté à la poulie', 'chest', array['shoulders']::text[], 'isolation', array['machines']::text[], 'intermediate', false, false, array['shoulder']::text[], 'Debout entre deux poulies, un pied en avant. Ramène les poignées devant toi en arc de cercle, coudes légèrement fléchis, puis reviens lentement.'),
  ('developpe-elastique', 'Développé à l''élastique', 'chest', array['triceps', 'shoulders']::text[], 'push_horizontal', array['resistance_bands']::text[], 'beginner', true, false, array[]::text[], 'Élastique fixé derrière toi à hauteur de poitrine. Pousse les poignées vers l''avant jusqu''à bras tendus, puis reviens en contrôlant.'),
  ('dips', 'Dips aux barres parallèles', 'triceps', array['chest', 'shoulders']::text[], 'push_vertical', array['machines']::text[], 'advanced', true, false, array['shoulder', 'elbow']::text[], 'En appui sur les barres, buste légèrement penché. Descends jusqu''à ce que les épaules soient à hauteur des coudes, pas plus bas, puis pousse.'),
  ('tractions', 'Tractions', 'back', array['biceps', 'forearms']::text[], 'pull_vertical', array['pull_up_bar']::text[], 'advanced', true, false, array['shoulder', 'elbow']::text[], 'Suspendu, mains un peu plus larges que les épaules. Tire en ramenant les coudes vers les hanches jusqu''à passer le menton au-dessus de la barre, puis redescends complètement.'),
  ('tractions-assistees-elastique', 'Tractions assistées à l''élastique', 'back', array['biceps']::text[], 'pull_vertical', array['pull_up_bar', 'resistance_bands']::text[], 'intermediate', true, false, array['shoulder']::text[], 'Accroche un élastique à la barre et place un pied ou un genou dedans. Tire comme une traction : l''élastique t''aide surtout en bas du mouvement.'),
  ('tirage-vertical', 'Tirage vertical à la poulie', 'back', array['biceps']::text[], 'pull_vertical', array['machines']::text[], 'beginner', true, false, array[]::text[], 'Assis, cuisses calées. Tire la barre vers le haut de la poitrine en ramenant les coudes le long du corps, buste légèrement incliné, puis remonte lentement.'),
  ('tirage-vertical-elastique', 'Tirage vertical à l''élastique', 'back', array['biceps']::text[], 'pull_vertical', array['resistance_bands']::text[], 'beginner', true, false, array[]::text[], 'Élastique fixé en hauteur. À genoux ou assis, tire les poignées vers le bas jusqu''aux épaules en serrant les omoplates.'),
  ('rowing-barre', 'Rowing à la barre', 'back', array['biceps', 'hamstrings']::text[], 'pull_horizontal', array['barbell']::text[], 'intermediate', true, false, array['lower_back']::text[], 'Buste penché à environ 45°, dos plat, genoux fléchis. Tire la barre vers le nombril en serrant les omoplates, puis redescends sans arrondir le dos.'),
  ('rowing-haltere-un-bras', 'Rowing haltère à un bras', 'back', array['biceps']::text[], 'pull_horizontal', array['dumbbells', 'bench']::text[], 'beginner', true, false, array[]::text[], 'Une main et un genou sur le banc, dos plat. Tire l''haltère vers la hanche en gardant le coude près du corps, puis redescends bras tendu.'),
  ('tirage-horizontal', 'Tirage horizontal à la poulie', 'back', array['biceps']::text[], 'pull_horizontal', array['machines']::text[], 'beginner', true, false, array[]::text[], 'Assis, pieds calés, dos droit. Tire la poignée vers le ventre en serrant les omoplates, sans balancer le buste, puis reviens lentement.'),
  ('rowing-inverse', 'Rowing inversé', 'back', array['biceps', 'core']::text[], 'pull_horizontal', array['pull_up_bar']::text[], 'intermediate', true, false, array[]::text[], 'Sous une barre basse, corps gainé, talons au sol. Tire la poitrine vers la barre, puis redescends bras tendus. Plus le corps est vertical, plus c''est facile.'),
  ('rowing-elastique', 'Rowing à l''élastique', 'back', array['biceps']::text[], 'pull_horizontal', array['resistance_bands']::text[], 'beginner', true, false, array[]::text[], 'Élastique fixé devant toi à hauteur de taille. Tire les poignées vers le ventre en serrant les omoplates, puis reviens en contrôlant.'),
  ('face-pull', 'Face pull à la poulie', 'shoulders', array['back']::text[], 'pull_horizontal', array['machines']::text[], 'beginner', false, false, array[]::text[], 'Corde à hauteur du visage. Tire vers le front en écartant les mains et en ouvrant les coudes vers l''extérieur, puis reviens lentement.'),
  ('developpe-militaire-barre', 'Développé militaire à la barre', 'shoulders', array['triceps', 'core']::text[], 'push_vertical', array['barbell']::text[], 'intermediate', true, false, array['shoulder', 'lower_back']::text[], 'Debout, barre sur le haut de la poitrine, fessiers et abdominaux serrés. Pousse la barre au-dessus de la tête en passant près du visage, sans cambrer le bas du dos.'),
  ('developpe-epaules-halteres', 'Développé épaules aux haltères', 'shoulders', array['triceps']::text[], 'push_vertical', array['dumbbells']::text[], 'beginner', true, false, array['shoulder']::text[], 'Assis ou debout, haltères à hauteur des épaules. Pousse vers le haut jusqu''à bras presque tendus, puis redescends jusqu''aux oreilles.'),
  ('developpe-epaules-machine', 'Développé épaules à la machine', 'shoulders', array['triceps']::text[], 'push_vertical', array['machines']::text[], 'beginner', true, false, array[]::text[], 'Règle le siège pour que les poignées partent à hauteur des épaules. Pousse vers le haut et redescends lentement.'),
  ('developpe-epaules-elastique', 'Développé épaules à l''élastique', 'shoulders', array['triceps']::text[], 'push_vertical', array['resistance_bands']::text[], 'beginner', true, false, array[]::text[], 'Debout sur l''élastique, poignées à hauteur des épaules. Pousse au-dessus de la tête, puis redescends en contrôlant.'),
  ('pompes-pike', 'Pompes piquées (pike)', 'shoulders', array['triceps']::text[], 'push_vertical', array[]::text[], 'intermediate', true, false, array['shoulder', 'wrist']::text[], 'Bassin haut, corps en V inversé. Fléchis les coudes pour amener le haut de la tête vers le sol devant les mains, puis pousse.'),
  ('elevations-laterales', 'Élévations latérales', 'shoulders', array[]::text[], 'isolation', array['dumbbells']::text[], 'beginner', false, false, array[]::text[], 'Debout, haltères le long du corps. Monte les bras sur les côtés jusqu''à hauteur des épaules, coudes légèrement fléchis, sans élan, puis redescends lentement.'),
  ('elevations-laterales-elastique', 'Élévations latérales à l''élastique', 'shoulders', array[]::text[], 'isolation', array['resistance_bands']::text[], 'beginner', false, false, array[]::text[], 'Debout sur l''élastique. Monte les bras sur les côtés jusqu''à hauteur des épaules, puis redescends en contrôlant.'),
  ('oiseau-halteres', 'Oiseau aux haltères', 'shoulders', array['back']::text[], 'isolation', array['dumbbells']::text[], 'beginner', false, false, array['lower_back']::text[], 'Buste penché en avant, dos plat. Écarte les bras sur les côtés en serrant les omoplates, coudes légèrement fléchis, puis redescends.'),
  ('curl-halteres', 'Curl aux haltères', 'biceps', array['forearms']::text[], 'isolation', array['dumbbells']::text[], 'beginner', false, false, array[]::text[], 'Debout, coudes collés au corps. Fléchis les bras en tournant les paumes vers le haut, puis redescends complètement sans balancer.'),
  ('curl-barre', 'Curl à la barre', 'biceps', array['forearms']::text[], 'isolation', array['barbell']::text[], 'beginner', false, false, array['elbow']::text[], 'Debout, prise en supination à largeur d''épaules. Monte la barre en gardant les coudes fixes, puis redescends lentement.'),
  ('curl-marteau', 'Curl marteau', 'biceps', array['forearms']::text[], 'isolation', array['dumbbells']::text[], 'beginner', false, false, array[]::text[], 'Paumes face à face, comme pour tenir un marteau. Fléchis les bras sans décoller les coudes, puis redescends.'),
  ('curl-elastique', 'Curl à l''élastique', 'biceps', array[]::text[], 'isolation', array['resistance_bands']::text[], 'beginner', false, false, array[]::text[], 'Debout sur l''élastique, coudes au corps. Fléchis les bras, puis redescends en contrôlant la tension.'),
  ('curl-poulie', 'Curl à la poulie', 'biceps', array[]::text[], 'isolation', array['machines']::text[], 'beginner', false, false, array[]::text[], 'Face à la poulie basse, coudes au corps. Fléchis les bras, marque un temps en haut, puis reviens lentement.'),
  ('extension-triceps-poulie', 'Extension des triceps à la poulie', 'triceps', array[]::text[], 'isolation', array['machines']::text[], 'beginner', false, false, array[]::text[], 'Face à la poulie haute, coudes collés au corps. Pousse la barre ou la corde vers le bas jusqu''à bras tendus, puis remonte sans bouger les coudes.'),
  ('extension-triceps-haltere', 'Extension des triceps à l''haltère au-dessus de la tête', 'triceps', array[]::text[], 'isolation', array['dumbbells']::text[], 'beginner', false, false, array['elbow', 'shoulder']::text[], 'Assis, un haltère tenu à deux mains au-dessus de la tête. Descends-le derrière la nuque en pliant les coudes, qui restent pointés vers le haut, puis remonte.'),
  ('dips-banc', 'Dips sur banc', 'triceps', array['chest']::text[], 'isolation', array['bench']::text[], 'beginner', false, false, array['shoulder', 'wrist']::text[], 'Mains sur le bord du banc derrière toi, jambes devant. Descends en pliant les coudes vers l''arrière jusqu''à 90°, puis pousse.'),
  ('extension-triceps-elastique', 'Extension des triceps à l''élastique', 'triceps', array[]::text[], 'isolation', array['resistance_bands']::text[], 'beginner', false, false, array[]::text[], 'Élastique fixé en hauteur. Coudes au corps, tends les bras vers le bas, puis reviens en contrôlant.'),
  ('pompes-serrees', 'Pompes mains serrées', 'triceps', array['chest']::text[], 'push_horizontal', array[]::text[], 'intermediate', true, false, array['wrist', 'elbow']::text[], 'Mains sous les épaules, coudes qui frôlent le buste. Descends la poitrine vers les mains, puis pousse.'),
  ('squat-barre', 'Squat à la barre', 'quadriceps', array['glutes', 'core']::text[], 'squat', array['barbell']::text[], 'intermediate', true, false, array['knee', 'lower_back']::text[], 'Barre sur le haut du dos, pieds à largeur d''épaules. Descends en poussant les hanches en arrière et les genoux dans l''axe des pieds, dos droit, puis remonte en poussant dans le sol. Utilise des sécurités.'),
  ('goblet-squat', 'Goblet squat', 'quadriceps', array['glutes', 'core']::text[], 'squat', array['dumbbells']::text[], 'beginner', true, false, array['knee']::text[], 'Un haltère tenu contre la poitrine. Descends entre tes genoux, buste droit, puis remonte en poussant dans les talons.'),
  ('goblet-squat-kettlebell', 'Goblet squat au kettlebell', 'quadriceps', array['glutes', 'core']::text[], 'squat', array['kettlebell']::text[], 'beginner', true, false, array['knee']::text[], 'Kettlebell tenu par les anses contre la poitrine. Descends buste droit, genoux dans l''axe des pieds, puis remonte.'),
  ('squat-poids-du-corps', 'Squat au poids du corps', 'quadriceps', array['glutes']::text[], 'squat', array[]::text[], 'beginner', true, false, array['knee']::text[], 'Pieds à largeur d''épaules, bras devant. Descends comme pour t''asseoir, talons au sol, puis remonte. Tu peux t''aider d''une chaise derrière toi.'),
  ('presse-cuisses', 'Presse à cuisses', 'quadriceps', array['glutes']::text[], 'squat', array['machines']::text[], 'beginner', true, false, array['knee']::text[], 'Dos bien calé, pieds à largeur d''épaules sur la plateforme. Descends jusqu''à environ 90° aux genoux sans décoller le bas du dos, puis pousse sans verrouiller les genoux.'),
  ('squat-bulgare', 'Squat bulgare', 'quadriceps', array['glutes']::text[], 'lunge', array['dumbbells', 'bench']::text[], 'intermediate', true, false, array['knee']::text[], 'Pied arrière posé sur le banc, haltères en main. Descends le genou arrière vers le sol, buste droit, puis remonte en poussant sur la jambe avant.'),
  ('fentes-arriere', 'Fentes arrière', 'quadriceps', array['glutes']::text[], 'lunge', array[]::text[], 'beginner', true, false, array['knee']::text[], 'Fais un grand pas en arrière et descends le genou arrière près du sol, puis reviens à la position de départ. Alterne les jambes.'),
  ('fentes-marchees-halteres', 'Fentes marchées aux haltères', 'quadriceps', array['glutes']::text[], 'lunge', array['dumbbells']::text[], 'intermediate', true, false, array['knee']::text[], 'Haltères en main, avance en fentes : genou arrière près du sol, genou avant au-dessus de la cheville.'),
  ('leg-extension', 'Leg extension', 'quadriceps', array[]::text[], 'isolation', array['machines']::text[], 'beginner', false, false, array['knee']::text[], 'Assis, rouleau sur le bas des tibias. Tends les jambes, marque un temps, puis redescends lentement.'),
  ('montees-sur-banc', 'Montées sur banc', 'quadriceps', array['glutes']::text[], 'lunge', array['bench']::text[], 'beginner', true, false, array['knee']::text[], 'Monte sur le banc en poussant sur la jambe posée dessus, sans t''aider de l''autre, puis redescends en contrôlant.'),
  ('chaise-murale', 'Chaise contre le mur', 'quadriceps', array['glutes']::text[], 'isolation', array[]::text[], 'beginner', false, true, array['knee']::text[], 'Dos contre le mur, cuisses parallèles au sol, genoux au-dessus des chevilles. Tiens la position en respirant normalement.'),
  ('souleve-de-terre-roumain', 'Soulevé de terre roumain', 'hamstrings', array['glutes', 'back']::text[], 'hinge', array['barbell']::text[], 'intermediate', true, false, array['lower_back']::text[], 'Debout, barre contre les cuisses, genoux légèrement fléchis. Pousse les hanches en arrière en gardant le dos plat et la barre près des jambes, jusqu''à l''étirement des ischios, puis remonte.'),
  ('souleve-de-terre-roumain-halteres', 'Soulevé de terre roumain aux haltères', 'hamstrings', array['glutes']::text[], 'hinge', array['dumbbells']::text[], 'beginner', true, false, array['lower_back']::text[], 'Haltères devant les cuisses. Bascule le buste en poussant les hanches en arrière, dos plat, jusqu''à mi-tibia, puis remonte en serrant les fessiers.'),
  ('souleve-de-terre', 'Soulevé de terre', 'hamstrings', array['glutes', 'back', 'quadriceps']::text[], 'hinge', array['barbell']::text[], 'advanced', true, false, array['lower_back']::text[], 'Barre au-dessus du milieu des pieds. Saisis-la, dos plat, poitrine sortie. Pousse dans le sol pour te redresser en gardant la barre contre les jambes, puis repose-la en contrôlant.'),
  ('swing-kettlebell', 'Swing au kettlebell', 'glutes', array['hamstrings', 'core']::text[], 'hinge', array['kettlebell']::text[], 'intermediate', true, false, array['lower_back']::text[], 'Le mouvement vient des hanches, pas des bras : bascule le kettlebell entre les jambes, dos plat, puis projette les hanches vers l''avant pour l''envoyer à hauteur de poitrine.'),
  ('hip-thrust-barre', 'Hip thrust à la barre', 'glutes', array['hamstrings']::text[], 'hinge', array['barbell', 'bench']::text[], 'intermediate', true, false, array[]::text[], 'Haut du dos sur le banc, barre sur les hanches (avec une protection). Pousse les hanches vers le haut jusqu''à l''alignement épaules-genoux en serrant les fessiers, puis redescends.'),
  ('pont-fessier', 'Pont fessier', 'glutes', array['hamstrings']::text[], 'hinge', array[]::text[], 'beginner', false, false, array[]::text[], 'Allongé sur le dos, pieds à plat près des fesses. Monte le bassin en serrant les fessiers, marque un temps en haut, puis redescends.'),
  ('pont-fessier-une-jambe', 'Pont fessier sur une jambe', 'glutes', array['hamstrings']::text[], 'hinge', array[]::text[], 'intermediate', false, false, array[]::text[], 'Comme le pont fessier, une jambe tendue en l''air. Garde le bassin bien horizontal en montant.'),
  ('leg-curl', 'Leg curl', 'hamstrings', array[]::text[], 'isolation', array['machines']::text[], 'beginner', false, false, array[]::text[], 'Rouleau au-dessus des talons. Plie les genoux en ramenant les talons vers les fesses, puis reviens lentement.'),
  ('leg-curl-elastique', 'Leg curl à l''élastique', 'hamstrings', array[]::text[], 'isolation', array['resistance_bands']::text[], 'beginner', false, false, array[]::text[], 'Allongé sur le ventre, élastique fixé devant et passé autour des chevilles. Ramène les talons vers les fesses, puis reviens.'),
  ('mollets-debout', 'Extensions des mollets debout', 'calves', array[]::text[], 'isolation', array[]::text[], 'beginner', false, false, array['ankle']::text[], 'Avant des pieds sur une marche, talons dans le vide. Monte sur la pointe des pieds, marque un temps, puis descends les talons sous la marche.'),
  ('mollets-machine', 'Mollets à la machine', 'calves', array[]::text[], 'isolation', array['machines']::text[], 'beginner', false, false, array['ankle']::text[], 'Avant des pieds sur la plateforme. Monte sur la pointe des pieds le plus haut possible, puis descends lentement.'),
  ('gainage-planche', 'Planche (gainage)', 'core', array['shoulders']::text[], 'core', array[]::text[], 'beginner', false, true, array[]::text[], 'En appui sur les avant-bras et les pointes de pieds, corps aligné. Serre les fessiers et le ventre, sans laisser tomber le bassin.'),
  ('gainage-lateral', 'Gainage latéral', 'core', array['glutes']::text[], 'core', array[]::text[], 'beginner', false, true, array['shoulder']::text[], 'Sur le côté, en appui sur un avant-bras. Monte le bassin pour aligner épaules, hanches et pieds. Change de côté à chaque série.'),
  ('dead-bug', 'Dead bug', 'core', array[]::text[], 'core', array[]::text[], 'beginner', false, false, array[]::text[], 'Sur le dos, bras tendus vers le plafond, genoux à 90°. Allonge un bras et la jambe opposée sans décoller le bas du dos du sol, puis alterne.'),
  ('bird-dog', 'Bird dog', 'core', array['glutes', 'back']::text[], 'core', array[]::text[], 'beginner', false, false, array[]::text[], 'À quatre pattes, tends un bras et la jambe opposée en gardant le dos plat et le bassin immobile, puis alterne.'),
  ('releves-genoux-suspendu', 'Relevés de genoux suspendu', 'core', array['forearms']::text[], 'core', array['pull_up_bar']::text[], 'intermediate', false, false, array['shoulder']::text[], 'Suspendu à la barre, ramène les genoux vers la poitrine en enroulant le bassin, sans te balancer, puis redescends lentement.'),
  ('mountain-climbers', 'Mountain climbers', 'core', array['shoulders', 'cardio']::text[], 'core', array[]::text[], 'intermediate', false, true, array['wrist']::text[], 'En position de pompe, ramène alternativement les genoux vers la poitrine à un rythme soutenu, bassin stable.'),
  ('marche-du-fermier', 'Marche du fermier', 'full_body', array['forearms', 'core']::text[], 'carry', array['dumbbells']::text[], 'beginner', true, true, array[]::text[], 'Un haltère lourd dans chaque main, marche à petits pas, épaules basses et buste droit.'),
  ('burpees', 'Burpees', 'full_body', array['chest', 'quadriceps', 'cardio']::text[], 'cardio', array[]::text[], 'intermediate', true, false, array['knee', 'wrist']::text[], 'Accroupis, mains au sol, lance les pieds en arrière, ramène-les, puis saute bras en l''air. Version douce : sans pompe ni saut.')
on conflict (slug) where owner_id is null do update set
  name = excluded.name,
  primary_muscle = excluded.primary_muscle,
  secondary_muscles = excluded.secondary_muscles,
  movement_pattern = excluded.movement_pattern,
  equipment = excluded.equipment,
  difficulty = excluded.difficulty,
  is_compound = excluded.is_compound,
  is_timed = excluded.is_timed,
  caution_areas = excluded.caution_areas,
  instructions = excluded.instructions;
